import React, { useState, useEffect } from 'react';

function App() {
  const [data, setData] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Y'lawej 3al variable d'environnement mta3 OpenShift, w ken fil local yesta3mel 8080
    const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8080';

    fetch(`${apiUrl}/api/hello`)
      .then(response => response.json())
      .then(data => {
        setData(data.message);
        setLoading(false);
      })
      .catch(error => {
        console.error("Erreur API:", error);
        setData("Erreur de connexion m3a l'API Spring Boot!");
        setLoading(false);
      });
  }, []);

  return (
    <div style={{ textAlign: 'center', marginTop: '50px', fontFamily: 'Arial' }}>
      <h1>Application 3 Tiers (React + Spring Boot + MariaDB)</h1>

      <div style={{ margin: '20px auto', padding: '20px', border: '2px solid #ccc', borderRadius: '10px', width: '50%' }}>
        <h3>Message mil Backend :</h3>
        {loading ? (
          <p>Y'chargi fi l'data...</p>
        ) : (
          <p style={{ color: 'green', fontWeight: 'bold', fontSize: '18px' }}>{data}</p>
        )}
      </div>
    </div>
  );
}

export default App;
